#: What a prompt can carry, and what each kind is called. Images reach the model as content
#: parts; audio is carried by path, because `Agent.compose` inlines pictures on every backend
#: while sound needs a runtime built with the encoders for it.
MEDIA = {
    '.png': ('image', 'image/png'),   '.jpg':  ('image', 'image/jpeg'),
    '.jpeg': ('image', 'image/jpeg'), '.gif':  ('image', 'image/gif'),
    '.webp': ('image', 'image/webp'),
    '.wav': ('audio', 'audio/wav'),   '.mp3':  ('audio', 'audio/mpeg'),
    '.m4a': ('audio', 'audio/mp4'),   '.ogg':  ('audio', 'audio/ogg'),
    '.flac': ('audio', 'audio/flac'), '.aac':  ('audio', 'audio/aac'),
}

MAX_MEDIA = 20 << 20   # bytes; past this a dropped file is a mistake, not an attachment
MAX_ATTACH = 8         # attachments on one prompt

#: How to ask a platform for a picture on the clipboard, in the order to try. Each writes PNG
#: to stdout, so the reply can be checked against the PNG signature rather than trusted.
CLIP_IMAGE = (('pngpaste', '-'),
              ('wl-paste', '--type', 'image/png'),
              ('xclip', '-selection', 'clipboard', '-t', 'image/png', '-o'))

def _human(n):
    "A byte count the way a person reads one."
    if n < 1024: return f'{n}B'
    for unit in ('KB', 'MB'):
        n /= 1024
        if n < 1024: return f'{n:.1f}{unit}'
    return f'{n / 1024:.1f}GB'

def media_path(s):
    """One path in whatever shape a terminal delivered it, or None.

    A file dropped on a prompt arrives as a bare path, a quoted path, a `file://` URI, or --
    on macOS -- with its spaces backslash-escaped, and some terminals wrap the whole thing in
    brackets. Only the first of those shapes used to attach anything, which is why dropping a
    picture on the prompt usually typed a path instead of attaching one.
    """
    s = str(s).strip().strip('[]').strip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in '"\'': s = s[1:-1]
    if s.startswith('file://'): s = unquote(urlparse(s).path)
    else: s = s.replace('\\ ', ' ')
    return Path(s).expanduser() if s else None

def is_media(p):
    "Whether `p` names a media file that exists."
    return p is not None and p.suffix.lower() in MEDIA and p.is_file()

def media_paths(text):
    """Every media file a paste names, or nothing when the paste is anything else.

    A paste attaches only when it is *nothing but* paths, so dropping three pictures attaches
    three while prose that mentions `docs/shot.png` in passing stays prose.
    """
    raw = str(text).strip().strip('[]').strip()
    if not raw: return []
    whole = media_path(raw)
    if is_media(whole): return [whole]        # one drop whose filename contains spaces
    try: toks = shlex.split(raw)
    except ValueError: return []
    paths = [media_path(t) for t in toks]
    return paths if paths and all(is_media(p) for p in paths) else []

#: `@path`, the file reference every other harness spells the same way.
ATTACH_REF = re.compile(r'(?<!\S)@(\S+)')

#: Punctuation a `@path` can pick up from the sentence it sits in, never from a filename.
TRAILING = '?!,;:.)]}\'"'

def attach_refs(text):
    """Media named `@path` inside a typed prompt.

    A reference at the end of a sentence carries the sentence's punctuation, so trailing marks
    come off one at a time until what is left names a file: `@shot.png?` is a question about a
    picture rather than a path to one.
    """
    out = []
    for m in ATTACH_REF.finditer(str(text or '')):
        tok = m.group(1)
        while tok:
            p = media_path(tok)
            if is_media(p):
                out.append(p)
                break
            if tok[-1] not in TRAILING: break
            tok = tok[:-1]
    return out

def clipboard_png():
    """A picture on the system clipboard as PNG bytes, or None when there is not one.

    Bracketed paste carries text and only text, so a copied *image* never arrives as input at
    all -- which is why pasting a screenshot into the prompt appeared to do nothing. Asking
    the platform for it is the only route to the gesture.
    """
    for cmd in CLIP_IMAGE:
        if shutil.which(cmd[0]) is None: continue
        try: out = subprocess.run(cmd, capture_output=True, timeout=5).stdout
        except Exception: continue
        if out[:8] == b'\x89PNG\r\n\x1a\n': return out
    return None

class Attachment:
    """One media file riding along with the next prompt.

    The bytes are read once, when the file is attached: what gets sent is then what was named
    and measured on screen, even if the file changes or goes away before the turn.
    """
    def __init__(self, path):
        self.path = Path(path).expanduser().resolve()
        self.kind, self.mime = MEDIA[self.path.suffix.lower()]
        self.data = self.path.read_bytes()

    @property
    def name(self): return self.path.name
    def __len__(self): return len(self.data)
    def label(self): return f'{self.name} ({_human(len(self))})'
    def line(self): return f'{self.kind}  {self.path}  {self.mime}  {_human(len(self))}'
    def __repr__(self): return f'Attachment({self.kind} {self.label()})'

def media_parts(atts):
    "The attachments that go out as model content parts: the pictures."
    return [a.data for a in atts if a.kind == 'image']

def media_note(atts):
    """What the message says about the files attached to it.

    Every attachment is named by absolute path, which is the part that survives whatever the
    runtime can accept: a model that cannot take sound inline can still reach a `.wav` through
    the file tools, and one that can take a picture is told where the picture came from.
    """
    if not atts: return ''
    rows = '\n'.join(a.line() for a in atts)
    note = ''
    if any(a.kind == 'image' for a in atts):
        note += '\nThe images above are attached to this message.'
    if any(a.kind == 'audio' for a in atts):
        note += '\nAudio is attached by path only; read it from the path above if you need its contents.'
    return f'\n\n<attachments>\n{rows}\n</attachments>{note}'

